(globalThis.CATALOGUE_RECORD_CHUNKS??=Object.create(null))[578]={"source_order":578,"notes":["Whether the faint upper-area traces are offset or erased pencil writing cannot be determined with certainty. They are illegible in all cases.","The pencil arcs at the top and lower right may be deliberate brackets or stray marks.","Faint ghosted writing across the upper half appears to be offset or show-through from facing pages (fol. 289 / fol. 290). It is not treated as target-page text.","Adjacent pages fol. 289 and fol. 290 are dense catalogue pages. None of their entries are recorded here.","The page was reviewed from the overview and from all six native-resolution tiles. Apart from the folio number, it is a ruled, unused catalogue page with no catalogue entries.","There is a curved pencil stroke resembling ')' in the upper area, at approximately [780,370,70,215]. No text is attached to it. It may be a deliberate bracket or a stray mark.","There is a faint curved pencil arc in the lower right, at approximately [2620,3440,180,340]. No text is attached to it.","Very faint illegible traces appear near the top ruling, at approximately [1300,580,160,70]. They are most probably offset or show-through from facing writing. No reading is possible.","Faint ghosted traces across the upper half appear to be offset or show-through from the facing pages. They are illegible and are not transcribed as target-page text.","Small ink specks appear at approximately [1920,1830,180,100], one of them resembling '6'. There is also an ink blot with dots at about [1540,3090,50,60], a short ink smear at the lower left at about [950,4310,120,60], and a dark speck at the right at about [2840,1110,30,40]. None of these is legible as text.","No entries from the adjacent pages fol. 289 or fol. 290 are recorded here.","The faint ghosted traces in the upper half, including those at about [1300,580,160,70], cannot be securely classified as offset or show-through rather than erased pencil writing on this page. They remain illegible in every case."],"records":[{"id":"css-prod-0578-r001","local_id":"r001","source_order":578,"folio":"289b","folio_label":"fol. 289b","sequence":1,"page_id":"1e0b045f-0c77-4ae7-8c84-f8cae40090c1","kind":"other","record_type":"non_catalogue_text","source_model_record_type":"non_catalogue_text","subtype":"folio_number","shelfmark":"","titleLiteral":"","titleNormalized":"","displayTitle":"Catalogue text","authorOrSource":"","source":"","subject":"","subjectGroup":"","date":"","extent":"","lines":"","script":"","incipit":"","transcription":"289^b.","annotations":["Pencil folio number in the top-left corner of the page.","The 'b' is written superscript above and after '289'.","A dot follows the numeral."],"uncertainties":["The faint ghosted traces in the upper half, including those at about [1300,580,160,70], cannot be securely classified as offset or show-through rather than erased pencil writing on this page. They remain illegible in every case."],"focused_readings":[],"reviewNotes":[],"editorialNotes":[],"relationships":[],"editorial_context":[],"block_ids":["b001"],"locations":[{"block_id":"b001","bbox":[360,325,150,160]}],"isCancelled":false,"needsReview":true,"human_verified":false,"verification_status":"machine_reviewed","change_audit":[],"sourceCitationURL":"https://iiif.bodleian.ox.ac.uk/iiif/canvas/1e0b045f-0c77-4ae7-8c84-f8cae40090c1.json","auditPath":"audit/pages/0578.json","attachedNotes":[],"resolvedRelationships":[],"attachedRecords":[]}]};
